from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False]*w for _ in range(h)]
    regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or seen[r][c]:
                continue
            q=deque([(r,c)]); seen[r][c]=True; cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and not seen[yy][xx] and grid[yy][xx]!=bg:
                        seen[yy][xx]=True; q.append((yy,xx))
            rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            area=(r1-r0+1)*(c1-c0+1)
            counts=Counter(grid[y][x] for y,x in cells)
            color,n=counts.most_common(1)[0]
            # A dense, multi-cell rectangle is a colored panel; tiny components are noise.
            if area>=4 and n>=4 and n/area>=0.68:
                regions.append((r0,r1,c0,c1,color))
    out=[[bg]*w for _ in range(h)]
    for r0,r1,c0,c1,color in regions:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): out[r][c]=color
    return out
